27: namespace sandstorm {
28: 
29: class BackupMain: public AbstractMain {
30: public:
31:   BackupMain(kj::ProcessContext& context): context(context) {}
32: 
33:   kj::MainFunc getMain() override {
34:     return kj::MainBuilder(context, "Sandstorm version " SANDSTORM_VERSION,
35:                            "Backs up the grain directory in <grain> to <file>, reading the grain "
36:                            "metadata struct on stdin. Or, restores the backup in <file>, "
37:                            "unpacking it to <grain>, and writing the metadata to stdout. In "
38:                            "backup mode, <file> can be `-` to write the data to stdout.")
39:         .addOption({'r', "restore"}, KJ_BIND_METHOD(*this, setRestore),
40:                    "Restore a backup, rather than create a backup.")
41:         .addOptionWithArg({"root"}, KJ_BIND_METHOD(*this, setRoot), "<root>",
42:                    "Set the \"root directory\" to map in, which contains the zip/unzip binaries.")
43:         .expectArg("<file>", KJ_BIND_METHOD(*this, setFile))
44:         .expectArg("<grain>", KJ_BIND_METHOD(*this, run))
45:         .build();
46:   }
47: 
48: private:
49:   kj::ProcessContext& context;
50:   bool restore = false;
51:   kj::StringPtr filename;
52:   kj::StringPtr root = "";
53: 
54:   bool setRestore() {
55:     restore = true;
56:     return true;
57:   }
58: 
59:   bool setFile(kj::StringPtr arg) {
60:     filename = arg;
61:     return true;
62:   }
63: 
64:   bool setRoot(kj::StringPtr arg) {
65:     root = arg;
66:     return true;
67:   }
68: 
69:   void writeSetgroupsIfPresent(const char *contents) {
70:     KJ_IF_MAYBE(fd, raiiOpenIfExists("/proc/self/setgroups", O_WRONLY | O_CLOEXEC)) {
71:       kj::FdOutputStream(kj::mv(*fd)).write(contents, strlen(contents));
72:     }
73:   }
74: 
75:   void writeUserNSMap(const char *type, kj::StringPtr contents) {
76:     kj::FdOutputStream(raiiOpen(kj::str("/proc/self/", type, "_map").cStr(), O_WRONLY | O_CLOEXEC))
77:         .write(contents.begin(), contents.size());
78:   }
79: 
80:   bool run(kj::StringPtr grainDir) {
81:     uid_t uid = getuid();
82:     gid_t gid = getgid();
83: 
84:     KJ_SYSCALL(unshare(CLONE_NEWUSER | CLONE_NEWNS));
85:     writeSetgroupsIfPresent("deny\n");
86:     writeUserNSMap("uid", kj::str("1000 ", uid, " 1\n"));
87:     writeUserNSMap("gid", kj::str("1000 ", gid, " 1\n"));
88: 
89:     // Mount root read-only.
90:     KJ_SYSCALL(mount(kj::str(root, "/").cStr(), "/tmp", nullptr,
91:                      MS_BIND | MS_REC | MS_RDONLY, nullptr));
92: 
93:     if (access("/tmp/dev/null", F_OK) != 0) {
94:       // Looks like we need to bind in /dev.
95:       KJ_SYSCALL(mount("/dev", "/tmp/dev", nullptr, MS_BIND, nullptr));
96:     }
97: 
98:     // Hide sensitive directories.
99:     KJ_SYSCALL(mount("tmpfs", "/tmp/proc", "tmpfs", 0, "size=32k,nr_inodes=8,mode=000"));
100:     KJ_SYSCALL(mount("tmpfs", "/tmp/var", "tmpfs", 0, "size=32k,nr_inodes=8,mode=000"));
101:     KJ_SYSCALL(mount("tmpfs", "/tmp/etc", "tmpfs", 0, "size=32k,nr_inodes=8,mode=000"));
102: 
103:     // Mount inner tmpfs.
104:     KJ_SYSCALL(mount("tmpfs", "/tmp/tmp", "tmpfs", 0, "size=8m,nr_inodes=128,mode=777"));
105: 
106:     // Bind in the grain's `data` (=`sandbox`).
107:     if (restore) {
108:       KJ_SYSCALL(mkdir(kj::str(grainDir, "/sandbox").cStr(), 0770));
109:     }
110:     KJ_SYSCALL(mkdir("/tmp/tmp/data", 0700));
111:     KJ_SYSCALL(mount(kj::str(grainDir, "/sandbox").cStr(), "/tmp/tmp/data", nullptr,
112:                      MS_BIND | (restore ? 0 : MS_RDONLY), nullptr));
113: 
114:     // Bind in the grain's `log`. When restoring, we discard the log.
115:     if (!restore) {
116:       KJ_SYSCALL(mknod("/tmp/tmp/log", S_IFREG | 0600, 0));
117:       KJ_SYSCALL(mount(kj::str(grainDir, "/log").cStr(), "/tmp/tmp/log", nullptr,
118:                        MS_BIND | MS_RDONLY, nullptr));
119:     }
120: 
121:     // Bind in the file.
122:     if (restore) {
123:       KJ_SYSCALL(mknod("/tmp/tmp/file.zip", S_IFREG | 0600, 0));
124:       KJ_SYSCALL(mount(filename.cStr(), "/tmp/tmp/file.zip", nullptr, MS_BIND, nullptr));
125:     } else if (filename != "-") {
126:       // Instead of binding, just open the file and we'll compress to stdout.
127:       KJ_SYSCALL(dup2(raiiOpen(filename, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC), STDOUT_FILENO));
128:     }
129: 
130:     // Use Andy's ridiculous pivot_root trick to place ourselves into the sandbox.
131:     // See supervisor-main.c++ for more discussion.
132:     {
133:       auto oldRootDir = raiiOpen("/", O_RDONLY | O_DIRECTORY | O_CLOEXEC);
134:       KJ_SYSCALL(syscall(SYS_pivot_root, "/tmp", "/tmp"));
135:       KJ_SYSCALL(fchdir(oldRootDir));
136:       KJ_SYSCALL(umount2(".", MNT_DETACH));
137:       KJ_SYSCALL(chdir("/tmp"));
138:     }
139: 
140:     // TODO(someday): Find a zip library that doesn't suck and use it instead of shelling out
141:     //   to zip/unzip.
142:     if (restore) {
143:       Subprocess({"unzip", "-q", "file.zip", "data/*", "metadata"}).waitForSuccess();
144: 
145:       // Read metadata file to stdout.
146:       kj::FdInputStream in(raiiOpen("metadata", O_RDONLY | O_CLOEXEC));
147:       kj::FdOutputStream out(STDOUT_FILENO);
148:       pump(in, out);
149:     } else {
150:       // Read stdin to metadata file.
151:       {
152:         kj::FdInputStream in(STDIN_FILENO);
153:         kj::FdOutputStream out(raiiOpen("metadata", O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC));
154:         pump(in, out);
155:       }
156: 
157:       Subprocess::Options zipOptions({"zip", "-qy@", "-"});
158:       auto inPipe = Pipe::make();
159:       zipOptions.stdin = inPipe.readEnd;
160:       Subprocess zip(kj::mv(zipOptions));
161:       inPipe.readEnd = nullptr;
162: 
163:       {
164:         kj::FdOutputStream out(kj::mv(inPipe.writeEnd));
165:         for (auto& entry: listDirectory(".")) {
166:           findFilesToZip(entry, out);
167:         }
168:       }
169: 
170:       zip.waitForSuccess();
171:     }
172: 
173:     return true;
174:   }
175: 
176:   static void pump(kj::InputStream& in, kj::OutputStream& out) {
177:     byte buffer[4096];
178:     while (size_t n = in.tryRead(buffer, 1, sizeof(buffer))) {
179:       out.write(buffer, n);
180:     }
181:   }
182: 
183:   void findFilesToZip(kj::StringPtr path, kj::OutputStream& out) {
184:     struct stat stats;
185:     KJ_SYSCALL(lstat(path.cStr(), &stats));
186:     if (S_ISREG(stats.st_mode) || S_ISLNK(stats.st_mode)) {
187:       // Regular file or link can be zipped; write to file stream.
188:       // If the path contains a newline, we cannot correctly pass it to `zip` since `zip` expects
189:       // one file per line. For security reasons, we must detect and filter out these files.
190:       // Hopefully this never happens legitimately?
191:       if (path.findFirst('\n') == nullptr) {
192:         kj::ArrayPtr<const byte> pieces[2];
193:         pieces[0] = path.asBytes();
194:         pieces[1] = kj::StringPtr("\n").asBytes();
195:         out.write(pieces);
196:       } else {
197:         KJ_LOG(ERROR, "tried to backup file containing newlines", path);
198:       }
199:     } else if (S_ISDIR(stats.st_mode)) {
200:       // Subdirectory; enumerate contents.
201:       for (auto& entry: listDirectory(path)) {
202:         findFilesToZip(kj::str(path, '/', entry), out);
203:       }
