495: kj::Promise<void> BackendImpl::pump(kj::AsyncInputStream& input, ByteStream::Client stream) {
496:   auto req = stream.writeRequest(capnp::MessageSize { 2100, 0 });
497:   auto orphanage = capnp::Orphanage::getForMessageContaining(
498:       kj::implicitCast<ByteStream::WriteParams::Builder>(req));
499:   auto orphan = orphanage.newOrphan<capnp::Data>(8192);
500:   auto buffer = orphan.get();
501: 
502:   return input.tryRead(buffer.begin(), 1, buffer.size())
503:       .then([&input,KJ_MVCAP(stream),KJ_MVCAP(req),KJ_MVCAP(orphan)](size_t n) mutable
504:             -> kj::Promise<void> {
505:     if (n == 0) {
506:       return kj::READY_NOW;
507:     }
508: 
509:     orphan.truncate(n);
510:     req.adoptData(kj::mv(orphan));
511: 
512:     // TODO(now): Parallelize writes.
513:     return req.send().then([&input,KJ_MVCAP(stream)](auto&&) mutable {
514:       return pump(input, kj::mv(stream));
515:     });
516:   });
517: }
