522:       kj::implicitCast<ByteStream::WriteParams::Builder>(req));
523:   auto orphan = orphanage.newOrphan<capnp::Data>(8192);
524:   auto buffer = orphan.get();
525: 
526:   size_t n = input.tryRead(buffer.begin(), 1, buffer.size());
527:   if (n == 0) {
528:     return kj::READY_NOW;
529:   }
530: 
531:   orphan.truncate(n);
532:   req.adoptData(kj::mv(orphan));
533: 
534:   // TODO(now): Parallelize writes.
535:   return req.send().then([&input,KJ_MVCAP(stream)](auto&&) mutable {
536:     return pump(input, kj::mv(stream));
